# getrennt da.
_known = [{"structure_id": 1, "name": "4-HWWF - WinterCo. Central Station",
           "character_id": 11},
          {"structure_id": 2, "name": "A-DDGY - Dockside Innovations",
           "character_id": 12},
          {"structure_id": 3, "name": "X47L-Q - Rogue Threshold",
           "character_id": 13}]
