import os as _os200
from eve_trader import store as _sto200, config as _cfg200
def _fnsrc_store(name):
    import re as _re200
    m = _re200.search(r"def " + name + r"\(.*?(?=\ndef |\Z)",
                      _st200_raw, _re200.S)
    return m.group(0) if m else ""
