def _cant263(owned):
    """Die Regel aus dem Produktivcode, hier auf die konstruierte Kette
    angewandt - dieselbe Bedingung, nicht eine nachgebaute."""
    raus = set()
    for _t in (301, 302):
        _s = _st263.get(_t)
        _k = ("intermediate_reactions" if _s == 1 else "composite_reactions")
        if _k not in owned:
            raus.add(_t)
    return raus


